(()=>{const a=window.BunnyAudio;if(!a)return;a.music('lobby');
 document.addEventListener('click',event=>{if(event.target.closest('button,a'))a.sfx('ui_click');});
 const button=document.createElement('button');button.className='rules-link';button.textContent='聲音';button.setAttribute('aria-label','大廳聲音設定');document.querySelector('.header-right')?.prepend(button);
 const dialog=document.createElement('dialog');dialog.setAttribute('aria-label','大廳聲音設定');dialog.style.cssText='background:#241824;color:#f7ead9;border:1px solid #b38989;border-radius:14px;padding:24px;width:min(390px,85vw)';dialog.innerHTML='<h2>聲音</h2>'+[['music','背景音樂'],['voice','角色配音'],['sfx','遊戲音效']].map(([key,label])=>'<label style="display:flex;align-items:center;gap:12px;margin:20px 0">'+label+'<input aria-label="'+label+'音量" data-channel="'+key+'" type="range" min="0" max="100" value="'+Math.round(a.settings[key]*100)+'" style="accent-color:#d294a7;flex:1;min-width:50px"></label>').join('')+'<p style="font-size:13px">音量設為 0 即靜音。</p><button type="button" class="audio-close" style="min-height:44px;padding:10px 24px;background:#ead2a8;color:#241824;border:1px solid #f7e4c4;border-radius:6px;font-weight:700">關閉</button>';document.body.append(dialog);button.onclick=()=>{a.unlock();dialog.showModal();};dialog.querySelector('button').onclick=()=>dialog.close();for(const input of dialog.querySelectorAll('input'))input.oninput=()=>a.set({[input.dataset.channel]:Number(input.value)/100});
})();
